import{_ as t,a as n,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Get Admin Menu","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-menu","title":"Get Admin Menu","description":"Returns the admin sidebar as a permission-filtered nested tree. The response below is trimmed to three top-level menus; a full-access token returns the whole sidebar.","query":"curl -X GET \\"https://your-domain.com/api/admin/menu\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","response":"[\\n  {\\n    \\"id\\": \\"menu\\",\\n    \\"tree\\": [\\n      {\\n        \\"key\\": \\"dashboard\\",\\n        \\"label\\": \\"Dashboard\\",\\n        \\"icon\\": \\"icon-dashboard\\",\\n        \\"sort\\": 1,\\n        \\"permission\\": \\"dashboard\\",\\n        \\"apiResource\\": { \\"rest\\": \\"/api/admin/dashboard/stats\\", \\"graphql\\": \\"statsAdminDashboard\\" },\\n        \\"children\\": []\\n      },\\n      {\\n        \\"key\\": \\"sales\\",\\n        \\"label\\": \\"Sales\\",\\n        \\"icon\\": \\"icon-sales\\",\\n        \\"sort\\": 2,\\n        \\"permission\\": \\"sales\\",\\n        \\"apiResource\\": null,\\n        \\"children\\": [\\n          {\\n            \\"key\\": \\"sales.orders\\",\\n            \\"label\\": \\"Orders\\",\\n            \\"icon\\": null,\\n            \\"sort\\": 1,\\n            \\"permission\\": \\"sales.orders\\",\\n            \\"apiResource\\": { \\"rest\\": \\"/api/admin/orders\\", \\"graphql\\": \\"adminOrders\\" },\\n            \\"children\\": []\\n          },\\n          {\\n            \\"key\\": \\"sales.rma\\",\\n            \\"label\\": \\"RMA\\",\\n            \\"icon\\": null,\\n            \\"sort\\": 7,\\n            \\"permission\\": \\"sales.rma\\",\\n            \\"apiResource\\": null,\\n            \\"children\\": [\\n              {\\n                \\"key\\": \\"sales.rma.requests\\",\\n                \\"label\\": \\"Requests\\",\\n                \\"icon\\": null,\\n                \\"sort\\": 1,\\n                \\"permission\\": \\"sales.rma.requests\\",\\n                \\"apiResource\\": { \\"rest\\": \\"/api/admin/rma/requests\\", \\"graphql\\": \\"adminReturns\\" },\\n                \\"children\\": []\\n              }\\n            ]\\n          }\\n        ]\\n      },\\n      {\\n        \\"key\\": \\"catalog\\",\\n        \\"label\\": \\"Catalog\\",\\n        \\"icon\\": \\"icon-product\\",\\n        \\"sort\\": 3,\\n        \\"permission\\": \\"catalog\\",\\n        \\"apiResource\\": null,\\n        \\"children\\": [\\n          {\\n            \\"key\\": \\"catalog.products\\",\\n            \\"label\\": \\"Products\\",\\n            \\"icon\\": null,\\n            \\"sort\\": 1,\\n            \\"permission\\": \\"catalog.products\\",\\n            \\"apiResource\\": { \\"rest\\": \\"/api/admin/catalog/products\\", \\"graphql\\": \\"adminCatalogProducts\\" },\\n            \\"children\\": []\\n          }\\n        ]\\n      }\\n    ]\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/navigation/menu.md","filePath":"api/rest-api/admin/navigation/menu.md","lastUpdated":1787725411000}'),d={name:"api/rest-api/admin/navigation/menu.md"};function r(s,e,i,l,c,h){return o(),n("div",null,e[0]||(e[0]=[a('<h1 id="get-admin-menu" tabindex="-1">Get Admin Menu <a class="header-anchor" href="#get-admin-menu" aria-label="Permalink to &quot;Get Admin Menu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/menu</code></td><td>GET</td></tr></tbody></table><p>Returns the admin sidebar as a nested tree, filtered to what the authenticated token is allowed to see. Use it to build a back-office navigation dynamically and to discover which API endpoint backs each screen.</p><p>The response is a <strong>one-element array</strong>, not a bare object. The single element carries <code>id</code> (always the literal <code>menu</code>) and the navigation under <code>tree</code>.</p><h2 id="node-shape" tabindex="-1">Node Shape <a class="header-anchor" href="#node-shape" aria-label="Permalink to &quot;Node Shape&quot;">​</a></h2><p>Every entry in <code>tree</code>, and in any nested <code>children</code>, carries the same seven keys:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>key</code></td><td>String</td><td>Unique node identifier, dot-delimited by depth (<code>sales.rma.requests</code>).</td></tr><tr><td><code>label</code></td><td>String</td><td>Menu title, translated into the request locale.</td></tr><tr><td><code>icon</code></td><td>String | null</td><td>Icon class. Set on top-level menus only; <code>null</code> at every deeper level.</td></tr><tr><td><code>sort</code></td><td>Integer</td><td>Display order among siblings.</td></tr><tr><td><code>permission</code></td><td>String</td><td>ACL key controlling visibility of this node.</td></tr><tr><td><code>apiResource</code></td><td>Object | null</td><td><code>{ rest, graphql }</code> naming the operations that back this screen, or <code>null</code>.</td></tr><tr><td><code>children</code></td><td>Array</td><td>Nested nodes, <code>[]</code> when the node is a leaf.</td></tr></tbody></table><p>Four details a client will otherwise get wrong:</p><ul><li><strong><code>sort</code> is not unique among siblings.</strong> The sidebar ships duplicate values — under Communications both Events and Campaigns are <code>sort: 2</code>, and at the top level both Settings and Integration are <code>8</code>. Sort with a stable tiebreak (<code>key</code>) or the order flips between renders.</li><li><strong><code>permission</code> always equals <code>key</code>.</strong> It is repeated for clarity, not because the two can diverge. Either one works as a lookup against <a href="/api/rest-api/admin/navigation/permissions.html">Get Admin Permissions</a>.</li><li><strong>The tree is three levels deep at most</strong> — <code>sales.rma.requests</code>, <code>marketing.promotions.catalog_rules</code>, <code>settings.taxes.tax_categories</code>. Recurse anyway; do not hard-code two levels.</li><li><strong><code>key</code> is the only safe loop key.</strong> Labels are translated and <code>sort</code> repeats.</li></ul><h2 id="the-apiresource-field" tabindex="-1">The apiResource Field <a class="header-anchor" href="#the-apiresource-field" aria-label="Permalink to &quot;The apiResource Field&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>rest</code></td><td>String</td><td>Path of the REST listing endpoint backing this screen — callable as-is.</td></tr><tr><td><code>graphql</code></td><td>String</td><td>Name of the GraphQL listing operation backing the same screen.</td></tr></tbody></table><p><code>apiResource</code> is resolved by matching the menu key against the admin API&#39;s own registered resources, so it stays correct as resources are added. It is <code>null</code> in two cases:</p><ul><li><strong>Group headers</strong> with no listing of their own — <code>sales</code>, <code>catalog</code>, <code>marketing</code>, <code>settings</code>, <code>sales.rma</code>, <code>settings.taxes</code>.</li><li><strong>Panel-only screens</strong> with no API counterpart — <code>integration.tokens</code>, <code>integration.history</code>, <code>settings.push_notification</code>.</li></ul><p>Being a parent does not by itself mean <code>null</code>: <code>customers</code> has children <em>and</em> an <code>apiResource</code>, and leaf nodes such as <code>cms</code> and <code>configuration</code> carry one too.</p><p>Only the <strong>listing</strong> endpoint is named. The detail, create, update, and delete endpoints for that screen are not in this payload — find them on that menu&#39;s own page.</p><h2 id="permission-filtering" tabindex="-1">Permission Filtering <a class="header-anchor" href="#permission-filtering" aria-label="Permalink to &quot;Permission Filtering&quot;">​</a></h2><p>The tree is scoped to the token:</p><ul><li>A token whose permission type is <code>all</code> sees every node.</li><li>A restricted token sees only the nodes it is granted; everything else is omitted entirely, not returned disabled.</li><li>A parent stays visible when at least one of its children is visible, so a permitted leaf is never orphaned.</li></ul><p>A token granted only <code>dashboard</code> receives a one-node tree. Two tokens on the same admin can therefore return different trees.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A request without a valid token returns HTTP <code>401</code> with <code>{&quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot;}</code>. Any valid token can call this endpoint — there is no separate permission gate on the menu itself, only the filtering above.</p>',21)]))}const m=t(d,[["render",r]]);export{u as __pageData,m as default};
